// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val, uint _am) public {
        // Bound inputs to reasonable values
        vm.assume(_val > 0 && _val < 1e30);
        vm.assume(_am > 0 && _am < 1e30);

        // Initialize the contract
        c.SetMinSum(_val);
        c.Initialized();

        // Record the MinSum before Collect
        uint minSumBefore = c.MinSum();

        // Attempt Collect (the bug changes MinSum only when not initialized, but since we initialized, it doesn't change here)
        // We need to provide enough balance for the call to possibly succeed
        address user = address(0x1234);
        vm.deal(user, _am);
        vm.prank(user);
        (bool success, ) = address(c).call{value: _am}("");
        if (success) {
            // Deposit happened
            vm.prank(user);
            c.Collect(_am);
        } else {
            // try again with a direct call
            vm.prank(user);
            c.Collect(_am);
        }

        uint minSumAfter = c.MinSum();

        // General rule: MinSum must never change after initialization
        assertTrue(minSumBefore == minSumAfter, "MinSum changed after Collect");
    }
}

